mkitem!{mkimpl!{# [extension (pub trait ProofTreeInferCtxtExt <'tcx >)] impl < 'tcx > InferCtxt < 'tcx > { fn visit_proof_tree < V : ProofTreeVisitor < 'tcx > > (& self , goal : Goal < 'tcx , ty :: Predicate < 'tcx > > , visitor : & mut V ,) -> V :: Result { self . visit_proof_tree_at_depth (goal , 0 , visitor) } fn visit_proof_tree_at_depth < V : ProofTreeVisitor < 'tcx > > (& self , goal : Goal < 'tcx , ty :: Predicate < 'tcx > > , depth : usize , visitor : & mut V ,) -> V :: Result { let (_ , proof_tree) = < & SolverDelegate < 'tcx > > :: from (self) . evaluate_root_goal_for_proof_tree (goal , visitor . span ()) ; visitor . visit_goal (& InspectGoal :: new (self , depth , proof_tree , None , GoalSource :: Misc)) } }}}